def run_agent(llm, tools, question, max_steps=5):
    messages = [{"role": "user", "content": question}]
    steps = 0
    while steps < max_steps:
        reply = llm(list(messages))                 # the model gets a copy, so it cannot change our record
        steps += 1
        if "final" in reply:
            messages.append({"role": "assistant", "content": reply["final"]})
            return {"answer": reply["final"], "steps": steps, "messages": messages}

        name, args = reply["tool"], reply.get("args", {})
        messages.append({"role": "assistant", "tool": name, "args": args})
        if name not in tools:
            content = f"error: unknown tool {name}"
        else:
            try:
                content = str(tools[name](**args))
            except Exception as error:               # tell the model what went wrong; it may be able to fix its call
                content = f"error: {type(error).__name__}: {error}"
        messages.append({"role": "tool", "name": name, "content": content})
    return {"answer": None, "steps": steps, "messages": messages}
